// Generated by scripts/build-glossary-data.mjs from content-source/glossary. Do not edit by hand.
export const GLOSSARY_SHARD = Object.freeze({"airdrop":{"slug":"airdrop","cat":"basics","en":"Airdrop","contentLocale":"es","term":"Airdrop","aka":["airdrops","lanzamiento aéreo"],"short":"Un airdrop es una distribución gratuita de tokens que un proyecto envía a ciertas direcciones, normalmente para recompensar a usuarios tempranos, repartir la gobernanza o promocionar un lanzamiento.","body":["Hay varios tipos. Algunos airdrops recompensan a quienes usaron un protocolo antes de que tuviera token, según criterios que el proyecto publica después. Otros se reparten entre quienes tienen un activo concreto, y algunos exchanges organizan campañas de distribución para sus usuarios.","Para reclamar, sueles conectar tu wallet a la web oficial y firmar una transacción. Ahí está el riesgo: los estafadores crean webs falsas que imitan a la oficial y te piden aprobaciones que les permiten vaciar tu wallet. También envían tokens sin valor a tu dirección para atraerte a esas webs.","Los tokens recibidos por airdrop pueden tener tratamiento fiscal en tu país, y a menudo su precio cae tras el reparto porque muchos receptores venden. Que un airdrop sea gratis no significa que no tenga costes: gas, tiempo y riesgo de seguridad."],"example":["Supón que un protocolo reparte 1.200 tokens a cada dirección que hizo al menos 5 operaciones antes de cierta fecha. El token empieza a cotizar a 0,80 ",["USDT","usdt"],", así que tu asignación vale 960 USDT. Reclamar cuesta 3 USDT de gas. Si esperas una semana y el precio baja a 0,50 USDT, la asignación vale 600 USDT. Por otro lado, si aparecen en tu wallet 5.000 tokens desconocidos con un enlace para \"canjearlos\", lo prudente es no interactuar."],"mistakes":["Conectar tu wallet a un enlace de airdrop recibido por mensaje directo o en comentarios.","Firmar aprobaciones ilimitadas para reclamar un token desconocido.","Dar por hecho que un airdrop futuro está garantizado por usar un protocolo."],"faq":[{"q":"¿Los airdrops son gratis?","a":"El token es gratuito, pero reclamarlo puede costar gas y exponerte a estafas. Además, en muchos países los tokens recibidos pueden tributar."},{"q":"¿Cómo sé si un airdrop es real?","a":"Verifica el anuncio en los canales oficiales del proyecto y entra a su web escribiendo la dirección tú mismo. Desconfía de cualquier airdrop que llegue por mensaje privado o te pida la frase semilla."}],"title":"¿Qué es un airdrop en cripto? Cómo funciona","description":"Qué es un airdrop de criptomonedas, cómo se reclaman los tokens, cómo detectar airdrops falsos y qué costes ocultos tienen.","related":[["phishing","Phishing","El phishing es un fraude en el que alguien se hace pasar por un exchange, billetera o proyecto conocido para que entregues tus contraseñas, tu frase semilla o firmes una transacción maliciosa."],["token-approval","Aprobación de tokens (allowance)","Una aprobación de tokens es un permiso que firmas en tu billetera para que un contrato inteligente pueda mover una cantidad determinada de un token tuyo sin pedirte firma cada vez."],["governance-token","Token de gobernanza","Un token de gobernanza es un token que da derecho a proponer y votar cambios en un protocolo o DAO, como comisiones, presupuestos o actualizaciones de sus contratos."],["launchpool","Launchpool","Un Launchpool es un producto de exchange en el que bloqueas o depositas ciertos tokens durante unos días y recibes a cambio tokens de un proyecto nuevo antes o justo cuando empieza a cotizar."],["rug-pull","Rug pull","Un rug pull es una estafa en la que los creadores de un token o proyecto retiran la liquidez o venden de golpe sus tokens y desaparecen, dejando a los inversores con activos casi sin valor."]],"lesson":{"id":"E11","slug":"scam-red-flags","ep":11,"title":"Alguien dice que te hará ganar dinero. Primero mira qué te pide."},"coin":null,"tool":null,"cta":false},"centralized-exchange":{"slug":"centralized-exchange","cat":"trading","en":"Centralized exchange (CEX)","contentLocale":"es","term":"Exchange centralizado (CEX)","aka":["CEX","exchange","casa de cambio cripto","plataforma de intercambio"],"short":"Un exchange centralizado (CEX) es una empresa que opera una plataforma donde compras, vendes y operas criptomonedas, custodia tus fondos y empareja las órdenes de los usuarios en su propio libro de órdenes.","body":[["Binance, OKX, Bybit, Bitget, Coinbase y Kraken son ejemplos de exchanges centralizados. Te registras, verificas tu identidad (",["KYC","kyc"],"), depositas dinero fiat o cripto y operas spot, futuros u otros productos. El exchange guarda tus fondos en sus wallets: tú ves un saldo en tu cuenta."],["Las ventajas son la ",["liquidez","liquidity"],", la facilidad para pasar de moneda local a cripto, la atención al cliente y la variedad de productos. El riesgo principal es la custodia: si el exchange sufre un hackeo, quiebra o congela retiros, tus fondos dependen de él. Por eso muchos publican pruebas de reservas."],["Los exchanges difieren en comisiones (maker y taker), productos disponibles en tu país, métodos de depósito, licencias y límites de retiro. Conviene comparar estas condiciones y activar la ",["autenticación en dos pasos","two-factor-authentication"]," y las listas blancas de direcciones."]],"example":["Supón que operas 10.000 ",["USDT","usdt"]," al mes en spot. En un exchange con ",["comisión taker","maker-taker-fees"]," de 0,10 % pagas 10 USDT al mes; en otro con 0,08 %, pagas 8. En un año, la diferencia es de 24 USDT. Si además operas futuros por 100.000 USDT al mes con una diferencia de 0,01 % en la comisión taker, la diferencia anual llega a 120 USDT. Son cifras ilustrativas; revisa la tabla de comisiones vigente de cada exchange."],"mistakes":["Dejar todos tus fondos en un solo exchange sin pensar en el riesgo de custodia.","No activar la autenticación en dos pasos ni la lista blanca de direcciones de retiro.","Elegir exchange solo por un bono de bienvenida sin mirar comisiones, liquidez y regulación."],"faq":[{"q":"¿Qué diferencia hay entre un CEX y un DEX?","a":"En un CEX una empresa custodia tus fondos y empareja las órdenes. En un DEX operas desde tu propia wallet con contratos inteligentes, sin entregar la custodia."},{"q":"¿Es seguro guardar cripto en un exchange?","a":"Depende del exchange y de tu configuración de seguridad. Para cantidades que no vas a operar, muchos usuarios prefieren una wallet propia."}],"title":"¿Qué es un exchange centralizado (CEX)?","description":"Qué es un exchange centralizado de criptomonedas, cómo custodia tus fondos, sus ventajas y riesgos, y qué comparar entre plataformas.","related":[["dex","Exchange descentralizado (DEX)","Un exchange descentralizado (DEX) es una plataforma de intercambio de cripto que funciona con contratos inteligentes, donde operas directamente desde tu billetera sin entregar la custodia de tus fondos."],["kyc","KYC (conoce a tu cliente)","El KYC es el proceso de verificación de identidad que exigen los exchanges y otros servicios regulados para confirmar quién eres antes de dejarte operar o retirar fondos."],["proof-of-reserves","Prueba de reservas (PoR)","La prueba de reservas es un método con el que un exchange demuestra que tiene en sus billeteras activos suficientes para cubrir los saldos que sus clientes tienen depositados."],["custodial-wallet","Billetera custodial","Una billetera custodial es una billetera en la que un tercero, normalmente un exchange o una empresa, guarda las claves privadas y controla los fondos en nombre del usuario."],["maker-taker-fees","Comisiones maker y taker","Las comisiones maker y taker son las dos tarifas que cobra un exchange según tu orden añada liquidez al libro de órdenes (maker) o la retire al ejecutarse de inmediato (taker)."]],"lesson":{"id":"E03","slug":"exchange-vs-wallet","ep":3,"title":"¿Dónde están mis monedas? Exchange vs billetera"},"coin":null,"tool":"/exchanges","cta":true},"support-and-resistance":{"slug":"support-and-resistance","cat":"trading","en":"Support and resistance","contentLocale":"es","term":"Soporte y resistencia","aka":["soporte","resistencia","niveles clave"],"short":"Soporte y resistencia son zonas de precio donde la caída tiende a frenarse (soporte) o la subida tiende a detenerse (resistencia), porque ahí se concentran compradores o vendedores.","body":["Un soporte aparece donde el precio rebotó varias veces hacia arriba: muchos participantes consideran barato ese nivel y compran. Una resistencia aparece donde el precio fue rechazado varias veces: muchos venden o toman beneficios. Son zonas aproximadas, no líneas exactas.","Cuando una resistencia se rompe con fuerza y volumen, a menudo pasa a actuar como soporte, y al revés. Los números redondos, los máximos históricos y los mínimos recientes suelen funcionar como niveles psicológicos.",["Los traders usan estos niveles para planificar entradas, colocar el ",["stop loss","stop-loss"]," un poco más allá del soporte o resistencia y fijar objetivos de ",["take profit","take-profit"],". Recuerda que en cripto las mechas pueden perforar un nivel por un momento y activar muchos stops a la vez, así que deja algo de margen."]],"example":["Supón que SOL rebota tres veces en la zona de 140 ",["USDT","usdt"]," y es rechazado dos veces cerca de 165. Decides comprar en 142 con un stop loss en 135, por debajo del soporte, y un objetivo en 163, justo antes de la resistencia. Arriesgas 7 USDT por SOL para intentar ganar 21: una ",["relación riesgo-beneficio","risk-reward-ratio"]," de 1 a 3. Si el precio cierra con fuerza por encima de 165, esa zona podría convertirse en el nuevo soporte."],"mistakes":["Dibujar el soporte como una línea exacta y poner el stop justo en ella, donde se concentran muchos stops.","Asumir que un soporte aguantará siempre; cuantas más veces se prueba, más puede debilitarse.","Usar niveles de una temporalidad de 5 minutos para operaciones que mantendrás varias semanas."],"faq":[{"q":"¿Cómo se identifica un soporte en un gráfico?","a":"Busca zonas donde el precio rebotó varias veces hacia arriba, sobre todo con volumen alto. Cuantos más toques claros en temporalidades altas, más relevante suele ser."},{"q":"¿Qué pasa cuando se rompe una resistencia?","a":"Si la ruptura se confirma con cierre y volumen, la antigua resistencia suele actuar como soporte. Si el precio vuelve a caer por debajo, se habla de falsa ruptura."}],"title":"¿Qué son soporte y resistencia? Trading cripto","description":"Qué son los niveles de soporte y resistencia, cómo trazarlos en velas y cómo usarlos para colocar stop loss y objetivos.","related":[["candlestick-chart","Gráfico de velas japonesas","Un gráfico de velas japonesas muestra el precio de apertura, máximo, mínimo y cierre de un activo en cada periodo, dibujado como una vela con cuerpo y mechas."],["stop-loss","Stop loss (orden de stop)","Un stop loss es una orden que cierra automáticamente tu posición cuando el precio llega a un nivel que has fijado, para limitar la pérdida si el mercado va en tu contra."],["limit-order","Orden límite (limit order)","Una orden límite (limit order) es una instrucción para comprar o vender a un precio concreto o mejor: una compra límite solo se ejecuta a ese precio o por debajo, y una venta límite, a ese precio o por encima."],["all-time-high","Máximo histórico (all-time high, ATH)","El máximo histórico (all-time high o ATH) es el precio más alto que ha alcanzado un activo desde que empezó a cotizar, y su contrario es el mínimo histórico (ATL)."]],"lesson":{"id":"E15","slug":"read-a-candlestick","ep":15,"title":"Una vela: ¿qué cuatro cosas te dice?"},"coin":null,"tool":null,"cta":false},"dollar-cost-averaging":{"slug":"dollar-cost-averaging","cat":"trading","en":"Dollar-cost averaging (DCA)","contentLocale":"es","term":"Promediar costo en dólares (DCA)","aka":["DCA","dollar-cost averaging","compra recurrente","inversión periódica"],"short":"El DCA o promedio de costo en dólares es una estrategia que consiste en comprar una cantidad fija de dinero de un activo a intervalos regulares, sin importar su precio en cada momento.","body":[["En lugar de invertir todo de una vez, divides el capital en compras iguales, por ejemplo 100 ",["USDT","usdt"]," cada semana. Cuando el precio está bajo compras más unidades, y cuando está alto compras menos. Así tu precio medio de compra se suaviza y no dependes de acertar el momento exacto."],"El DCA reduce el estrés de decidir cuándo entrar y el riesgo de invertir todo justo en un máximo. No elimina las pérdidas: si el activo cae durante mucho tiempo, tu posición también perderá valor. Tampoco garantiza un mejor resultado que una compra única; en un mercado que sube sin pausa, comprar todo al principio habría salido mejor.","Muchos exchanges ofrecen compras recurrentes automáticas en spot. Revisa las comisiones de cada compra, porque en cantidades pequeñas pesan más, y decide de antemano durante cuánto tiempo mantendrás el plan."],"example":["Inviertes 200 USDT al mes en ",["BTC","bitcoin"]," durante cuatro meses. Los precios de compra son 50.000, 40.000, 45.000 y 55.000 USDT. Compras 0,004, 0,005, 0,004444 y 0,003636 BTC: en total unos 0,01708 BTC por 800 USDT. Tu precio medio es 800 / 0,01708, alrededor de 46.840 USDT, por debajo de la media simple de los cuatro precios (47.500), porque compraste más unidades cuando estaba barato."],"mistakes":["Abandonar el plan justo cuando el precio cae, que es cuando el DCA compra más unidades.","Hacer compras muy pequeñas con comisiones fijas que se comen buena parte de cada aporte.","Creer que el DCA protege de cualquier pérdida aunque el activo pierda valor de forma permanente."],"faq":[{"q":"¿El DCA funciona en criptomonedas?","a":"Es una forma de entrar de manera gradual y disciplinada en un mercado volátil. Suaviza el precio medio, pero el resultado final depende de cómo evolucione el activo."},{"q":"¿Cada cuánto conviene hacer DCA?","a":"No hay un intervalo perfecto; semanal o mensual son habituales. Lo importante es una cantidad que puedas mantener y comisiones bajas en cada compra."}],"title":"¿Qué es el DCA en cripto? Promedio de costo","description":"Qué es el DCA, cómo calcula tu precio medio con compras periódicas y qué límites tiene frente a una compra única.","related":[["hodl","HODL","HODL es la jerga cripto para mantener tus criptomonedas a largo plazo sin vender ante las caídas, nacida de un error tipográfico de \"hold\" en un foro de Bitcoin en 2013."],["volatility","Volatilidad","La volatilidad mide cuánto y con qué rapidez varía el precio de un activo; en cripto suele ser mucho mayor que en acciones o divisas, con movimientos diarios de varios puntos porcentuales."],["position-sizing","Tamaño de posición","El tamaño de posición es la cantidad de capital que asignas a una operación, calculada para que, si toca tu stop loss, pierdas solo un porcentaje fijo de tu cuenta."],["grid-trading-bot","Bot de trading en cuadrícula (grid)","Un bot de trading en cuadrícula es una herramienta automática que coloca órdenes de compra y venta escalonadas dentro de un rango de precios para ganar con las oscilaciones del mercado."],["spot-trading","Trading spot (al contado)","El trading spot o al contado es la compraventa directa de criptomonedas al precio actual, en la que recibes el activo de inmediato y pasa a ser tuyo, sin apalancamiento ni contratos de por medio."]],"lesson":{"id":"E16","slug":"position-sizing-basics","ep":16,"title":"Decide cuánto podrías perder antes de decidir cuánto comprar"},"coin":null,"tool":null,"cta":true},"usdt-margined-futures":{"slug":"usdt-margined-futures","cat":"derivatives","en":"USDT-margined (linear) futures","contentLocale":"es","term":"Futuros con margen en USDT (lineales)","aka":["futuros USDT-M","futuros lineales","USDT-margined","contratos lineales"],"short":"Los futuros con margen en USDT, o lineales, son contratos en los que el margen, las comisiones y las ganancias o pérdidas se calculan y liquidan en USDT.","body":[["Es el tipo de futuro más usado por traders minoristas. El tamaño se expresa en la moneda (por ejemplo 0,1 ",["BTC","bitcoin"],") y cada movimiento de 1 ",["USDT","usdt"]," en el precio cambia tu resultado en una cantidad fija. Por eso se llaman lineales: la relación entre precio y ganancia es directa."],["La gran ventaja es la simplicidad. Con un solo saldo en USDT puedes operar decenas de pares, y en ",["margen cruzado","cross-margin"]," ese saldo cubre todas tus posiciones. Calcular el riesgo también es sencillo, porque tu cuenta no cambia de valor por el simple movimiento del activo base."],["Algunos exchanges ofrecen además contratos con margen en ",["USDC","usdc"]," u otras ",["stablecoins","stablecoin"],", con la misma lógica. Recuerda que tu margen depende de la stablecoin: USDT lo emite Tether, y su paridad con el dólar es un riesgo distinto al del trading."]],"example":["Abres un largo de 0,5 BTC en un perpetuo BTC/USDT a 60.000, un valor nocional de 30.000 USDT, con ",["apalancamiento","leverage"]," 10x y 3.000 USDT de margen. Si el precio sube a 63.000, ganas 0,5 × 3.000 = 1.500 USDT, un 50 % del margen. Si cae a 58.000, pierdes 0,5 × 2.000 = 1.000 USDT. Cada 100 USDT de movimiento equivale siempre a 50 USDT de resultado."],"mistakes":["Calcular el beneficio sobre el margen y olvidar que la pérdida también se mide sobre el nocional.","Dejar todo el saldo en margen cruzado y que una sola posición mala consuma la cuenta.","Ignorar que el saldo depende de que USDT mantenga su paridad con el dólar."],"faq":[{"q":"¿Por qué se llaman futuros lineales?","a":"Porque la ganancia o pérdida en USDT cambia en proporción directa al precio: cada dólar de movimiento vale lo mismo para el mismo tamaño."},{"q":"¿Es mejor operar futuros en USDT o en moneda?","a":"Los USDT-M son más fáciles de calcular y gestionar. Los COIN-M sirven más para cubrir tenencias en la propia moneda."}],"title":"¿Qué son los futuros USDT-M o lineales?","description":"Qué son los futuros con margen en USDT, por qué se llaman lineales y cómo calcular tu resultado en un ejemplo sencillo.","related":[["coin-margined-futures","Futuros con margen en moneda (inversos)","Los futuros con margen en moneda, o inversos, son contratos en los que el margen y las ganancias o pérdidas se calculan en la propia criptomoneda, por ejemplo en BTC, y no en una stablecoin."],["perpetual-futures","Futuros perpetuos (perps)","Los futuros perpetuos son contratos de futuros sin fecha de vencimiento que siguen el precio spot gracias a pagos periódicos entre largos y cortos llamados tasa de financiación."],["usdt","USDT (Tether)","USDT es la stablecoin emitida por Tether que busca mantener un valor de 1 dólar estadounidense y que es la moneda base más usada en los exchanges de cripto."],["cross-margin","Margen cruzado","El margen cruzado es un modo en el que todo el saldo disponible de tu cuenta de futuros o margen sirve de garantía compartida para todas tus posiciones abiertas."]],"lesson":{"id":"E18","slug":"spot-vs-futures","ep":18,"title":"Spot vs futuros: no estás comprando lo mismo"},"coin":{"slug":"tether","name":"Tether","symbol":"USDT"},"tool":null,"cta":true},"open-interest":{"slug":"open-interest","cat":"derivatives","en":"Open interest","contentLocale":"es","term":"Interés abierto","aka":["open interest","OI","posiciones abiertas"],"short":"El interés abierto es el número o valor total de contratos de futuros u opciones que siguen abiertos en un momento dado y todavía no se han cerrado ni liquidado.","body":["Cada contrato tiene un comprador y un vendedor, así que el interés abierto cuenta cada contrato una sola vez, no dos. Si un trader abre un largo y otro abre un corto, el interés abierto sube en un contrato. Si ambos cierran, baja. Si uno le pasa su posición a otro, no cambia.","A diferencia del volumen, que mide cuánto se negoció en un periodo, el interés abierto mide cuánto capital sigue comprometido. Un precio que sube con interés abierto creciente sugiere que entran posiciones nuevas. Un precio que sube con interés abierto cayendo suele indicar cierres de cortos.",["Un interés abierto muy alto en relación con el tamaño del mercado significa mucho ",["apalancamiento","leverage"]," acumulado, y eso aumenta el riesgo de liquidaciones en cadena. Se suele mostrar en monedas o en dólares, por exchange o agregado."]],"example":["El lunes el interés abierto en ",["perpetuos","perpetual-futures"]," de ",["BTC","bitcoin"]," es de 100.000 BTC y el precio está en 60.000. El viernes el precio está en 64.000 y el interés abierto subió a 115.000 BTC: entraron 15.000 BTC en posiciones nuevas, unos 960 millones de ",["USDT","usdt"]," a 64.000. Si la ",["tasa de financiación","funding-rate"]," también es muy positiva, gran parte de esas posiciones probablemente son largas apalancadas, vulnerables a una caída brusca."],"mistakes":["Sumar largos y cortos como si el interés abierto contara cada lado por separado.","Confundir interés abierto con volumen de trading.","Comparar el interés abierto en monedas y en dólares sin ajustar por el cambio de precio."],"faq":[{"q":"¿Qué significa que suba el interés abierto?","a":"Que se están abriendo más posiciones de las que se cierran, es decir, entra capital nuevo en los derivados. No indica por sí solo si dominan largos o cortos."},{"q":"¿Qué diferencia hay entre interés abierto y volumen?","a":"El volumen mide lo negociado en un periodo; el interés abierto mide las posiciones que siguen vivas en un momento concreto."}],"title":"¿Qué es el interés abierto (open interest)?","description":"Qué es el interés abierto en futuros cripto, en qué se diferencia del volumen y cómo leerlo junto al precio y la financiación.","related":[["trading-volume","Volumen de trading","El volumen de trading es el valor total de un activo que se ha comprado y vendido en un periodo concreto, normalmente las últimas 24 horas."],["funding-rate","Tasa de financiación (funding rate)","La tasa de financiación es un pago periódico entre traders largos y cortos de futuros perpetuos que mantiene el precio del contrato cerca del precio spot."],["long-short-ratio","Ratio largos/cortos","El ratio largos/cortos compara cuántas cuentas o posiciones están en largo frente a cuántas están en corto en un mercado de futuros, y se usa como indicador del sentimiento."],["liquidation","Liquidación","La liquidación es el cierre forzoso de una posición apalancada por parte del exchange cuando tu margen ya no cubre el margen de mantenimiento exigido."]],"lesson":null,"coin":null,"tool":"/funding-rates","cta":false},"hot-wallet":{"slug":"hot-wallet","cat":"wallets-security","en":"Hot wallet","contentLocale":"es","term":"Billetera caliente (hot wallet)","aka":["hot wallet","wallet caliente","monedero caliente"],"short":"Una billetera caliente (hot wallet) es una billetera cripto cuyas claves se usan en un dispositivo conectado a internet, lo que la hace cómoda para operar a diario pero más expuesta a ataques.","body":[["Son billeteras calientes las apps móviles, las extensiones de navegador como MetaMask o Phantom y también las billeteras internas de los exchanges. Lo que tienen en común es que la ",["clave privada","private-key"]," está, o puede estar, en un equipo con conexión permanente."],["Su gran ventaja es la rapidez: puedes enviar fondos, conectarte a una ",["DEX","dex"]," o reclamar un ",["airdrop","airdrop"]," en segundos. El riesgo es que cualquier malware, extensión falsa o sitio de ",["phishing","phishing"]," que logre que firmes algo puede llegar a tus fondos."],["La práctica habitual es tratar la billetera caliente como una cartera de bolsillo: llevas solo lo que necesitas para operar y guardas el resto en una ",["billetera fría","cold-wallet"],". Si usas varias aplicaciones ",["DeFi","defi"],", también conviene separar una billetera caliente de \"uso diario\" de otra con más saldo que casi nunca firma nada."]],"example":"Imagina que tienes 4.000 USDT en total. Decides dejar 300 USDT en una extensión de navegador para probar protocolos DeFi y mover 3.700 USDT a una billetera de hardware. Un día firmas por error una aprobación en un sitio falso y el atacante vacía la extensión. Pierdes 300 USDT, es decir, el 7,5 % de tu saldo, en lugar del 100 %. La separación no evitó el error, pero limitó el daño.","mistakes":["Guardar todos los ahorros en una extensión de navegador que también usas para probar proyectos nuevos.","Instalar extensiones de billetera desde anuncios o enlaces en redes sociales en lugar de la tienda oficial.","Creer que una billetera caliente es insegura por definición y no usar ninguna buena práctica en ella."],"faq":[{"q":"¿Una billetera de exchange es una hot wallet?","a":"Sí, desde tu punto de vista es una billetera custodial en caliente. Los exchanges suelen guardar la mayor parte de los fondos en frío, pero tu saldo disponible se gestiona en sistemas conectados."},{"q":"¿Cuánto dinero conviene tener en una billetera caliente?","a":"Lo que necesites para operar en el corto plazo y estés dispuesto a arriesgar. El resto suele guardarse en una billetera fría."}],"title":"¿Qué es una billetera caliente (hot wallet)?","description":"Qué es una hot wallet, en qué se diferencia de una billetera fría y cómo limitar el riesgo si la usas para operar a diario.","related":[["cold-wallet","Billetera fría (almacenamiento en frío)","Una billetera fría es una forma de guardar cripto en la que las claves privadas se mantienen fuera de cualquier dispositivo conectado a internet, lo que reduce mucho el riesgo de robo remoto."],["hardware-wallet","Billetera de hardware","Una billetera de hardware es un dispositivo físico, del tamaño de un USB, que guarda las claves privadas en un chip aislado y firma las transacciones sin exponerlas al computador o al teléfono."],["non-custodial-wallet","Billetera no custodial (autocustodia)","Una billetera no custodial es una billetera cripto en la que solo tú controlas las claves privadas, de modo que nadie más puede mover, congelar ni recuperar tus fondos por ti."],["phishing","Phishing","El phishing es un fraude en el que alguien se hace pasar por un exchange, billetera o proyecto conocido para que entregues tus contraseñas, tu frase semilla o firmes una transacción maliciosa."]],"lesson":{"id":"E03","slug":"exchange-vs-wallet","ep":3,"title":"¿Dónde están mis monedas? Exchange vs billetera"},"coin":null,"tool":null,"cta":false},"seed-phrase":{"slug":"seed-phrase","cat":"wallets-security","en":"Seed phrase (recovery phrase)","contentLocale":"es","term":"Frase semilla (frase de recuperación)","aka":["seed phrase","frase de recuperación","palabras semilla","frase mnemónica"],"short":"Una frase semilla es una lista de 12 o 24 palabras que permite regenerar todas las claves privadas de una billetera, por lo que quien la tenga controla todos sus fondos.","body":["La mayoría de las billeteras siguen el estándar BIP-39: una lista de 2.048 palabras en inglés de la que se eligen 12, 18 o 24 en un orden concreto. A partir de esas palabras se derivan todas tus claves y direcciones, en varias blockchains a la vez.",["Por eso la frase semilla es más importante que la contraseña de la app. La contraseña solo protege el acceso en ese dispositivo; la frase semilla es la ",["billetera","crypto-wallet"]," completa. Cualquiera que la escriba en otra app tendrá exactamente tus mismos fondos."],["Una regla que no tiene excepciones: ningún exchange, billetera, soporte técnico ni proyecto legítimo te pedirá tu frase semilla. Los formularios para \"validar\", \"sincronizar\" o \"recibir un ",["airdrop","airdrop"],"\" que la piden son robos. Guárdala en papel o metal, fuera de línea, y en un lugar donde no la vea nadie más."]],"example":["Ana configura una billetera y recibe 12 palabras. Las anota en papel y guarda una copia en casa y otra en casa de un familiar de confianza. Dos años después pierde el teléfono con 1.500 ",["USDT","usdt"]," y 0,3 ",["ETH","ethereum"]," en la billetera. Instala la app en un teléfono nuevo, elige \"restaurar\", escribe las 12 palabras en el mismo orden y recupera los 1.500 USDT y los 0,3 ETH. Si hubiera cambiado el orden de dos palabras, la app habría generado otra billetera vacía o habría rechazado la frase."],"mistakes":["Guardar la frase en notas del teléfono, correo, nube o capturas de pantalla.","Escribirla en un sitio web o en un chat porque alguien dice ser del soporte.","Anotarla sin el orden correcto o con faltas de ortografía que impiden restaurarla."],"faq":[{"q":"¿Puedo cambiar mi frase semilla si creo que alguien la vio?","a":"No se puede cambiar una frase existente. Debes crear una billetera nueva con otra frase y mover todos los fondos a sus direcciones lo antes posible."},{"q":"¿La frase semilla es lo mismo que la clave privada?","a":"No. La frase semilla genera muchas claves privadas, una por cada dirección y red. Perder la frase equivale a perder todas esas claves."}],"title":"¿Qué es la frase semilla? Frase de recuperación cripto","description":"Qué es una frase semilla de 12 o 24 palabras, por qué controla todos tus fondos y cómo guardarla sin exponerla.","related":[["private-key","Clave privada","Una clave privada es un número secreto que demuestra que eres el dueño de una dirección cripto y que se usa para firmar las transacciones que mueven sus fondos."],["non-custodial-wallet","Billetera no custodial (autocustodia)","Una billetera no custodial es una billetera cripto en la que solo tú controlas las claves privadas, de modo que nadie más puede mover, congelar ni recuperar tus fondos por ti."],["phishing","Phishing","El phishing es un fraude en el que alguien se hace pasar por un exchange, billetera o proyecto conocido para que entregues tus contraseñas, tu frase semilla o firmes una transacción maliciosa."],["hardware-wallet","Billetera de hardware","Una billetera de hardware es un dispositivo físico, del tamaño de un USB, que guarda las claves privadas en un chip aislado y firma las transacciones sin exponerlas al computador o al teléfono."]],"lesson":{"id":"E11","slug":"scam-red-flags","ep":11,"title":"Alguien dice que te hará ganar dinero. Primero mira qué te pide."},"coin":null,"tool":null,"cta":false},"public-key":{"slug":"public-key","cat":"wallets-security","en":"Public key","contentLocale":"es","term":"Clave pública","aka":["public key","llave pública"],"short":"Una clave pública es el par visible de una clave privada: permite a la red verificar tus firmas y sirve de base para generar tu dirección de billetera, sin revelar la clave secreta.","body":[["La criptografía de clave pública funciona con un par matemático. La ",["clave privada","private-key"]," firma y la clave pública verifica. Calcular la pública a partir de la privada es fácil; hacer lo contrario no es factible en la práctica."],["En ",["Bitcoin","bitcoin"]," y ",["Ethereum","ethereum"],", la dirección que compartes no es exactamente la clave pública, sino un resultado más corto obtenido al aplicarle funciones hash. Eso añade una capa de protección y hace las direcciones más manejables."],["Para el usuario, lo importante es entender qué se puede compartir. La clave pública y la dirección pueden darse a cualquiera para recibir fondos; también existen claves públicas extendidas (xpub) que permiten ver todas las direcciones de una ",["billetera","crypto-wallet"],". Compartir una xpub no permite robar fondos, pero sí revela tu historial y saldo completos, así que conviene tratarla con discreción."]],"example":["Carlos quiere recibir 0,01 BTC. Su billetera toma la clave pública, le aplica funciones hash y le muestra una dirección que empieza por bc1. Carlos la comparte por chat. Cuando más tarde gasta 0,004 BTC, su firma y su clave pública quedan visibles en la transacción, y cualquier ",["nodo","node"]," puede comprobar que la firma corresponde a esa dirección. Los 0,006 BTC restantes siguen seguros, porque la clave privada nunca se publicó."],"mistakes":["Confundir la clave pública con la privada y tener miedo de compartir la dirección para recibir pagos.","Compartir una xpub con desconocidos sin saber que revela todo el historial de la billetera.","Pensar que la clave pública y la dirección son siempre idénticas en todas las redes."],"faq":[{"q":"¿Es seguro compartir mi clave pública?","a":"Sí, nadie puede mover tus fondos con ella. Solo ten en cuenta que puede revelar información sobre tus transacciones."},{"q":"¿Qué diferencia hay entre clave pública y dirección?","a":"La dirección suele ser una versión resumida de la clave pública mediante funciones hash, con un formato más corto y con control de errores."}],"title":"¿Qué es una clave pública en cripto?","description":"Qué es una clave pública, cómo se relaciona con la clave privada y la dirección, y qué puedes compartir sin riesgo.","related":[["private-key","Clave privada","Una clave privada es un número secreto que demuestra que eres el dueño de una dirección cripto y que se usa para firmar las transacciones que mueven sus fondos."],["wallet-address","Dirección de billetera","Una dirección de billetera es la cadena de caracteres que identifica dónde recibir criptomonedas en una red concreta, parecida a un número de cuenta que puedes compartir sin riesgo."],["blockchain","Blockchain (cadena de bloques)","Una blockchain o cadena de bloques es un registro digital compartido en el que las transacciones se agrupan en bloques encadenados entre sí, de modo que cambiar un dato antiguo exigiría rehacer todos los bloques posteriores."]],"lesson":{"id":"E09","slug":"pre-transfer-checklist","ep":9,"title":"Antes de transferir: no adivines ninguno de estos puntos"},"coin":null,"tool":null,"cta":false},"transaction-hash":{"slug":"transaction-hash","cat":"wallets-security","en":"Transaction hash (TxID)","contentLocale":"es","term":"Hash de transacción (TxID)","aka":["TxID","TxHash","hash","ID de transacción"],"short":"Un hash de transacción (TxID) es el identificador único de una transacción en la blockchain, que permite buscarla en un explorador de bloques y comprobar su estado.","body":[["Cada transacción se resume mediante una función hash en una cadena de caracteres fija. En ",["Ethereum","ethereum"]," y redes EVM suele empezar por 0x y tener 66 caracteres; en ",["Bitcoin","bitcoin"]," son 64 caracteres hexadecimales. Si pegas ese código en un ",["explorador de bloques","block-explorer"],", verás origen, destino, monto, comisión, bloque y número de ",["confirmaciones","block-confirmations"],"."],"El TxID es la prueba más útil cuando un depósito no llega. Te dice si la transacción existe, si está pendiente o fallida y a qué dirección y red se envió realmente. Los equipos de soporte de los exchanges casi siempre lo piden.","Un TxID no es secreto, pero sí revela las direcciones implicadas. Compártelo solo con el soporte oficial o con quien deba verificar el pago."],"example":["Retiras 0,05 ETH de un exchange y, después de 20 minutos, tu ",["billetera","crypto-wallet"]," no los muestra. En el historial de retiros copias el TxID y lo pegas en un explorador de Ethereum. Ves que la transacción está en estado \"Success\", con 0,05 ETH enviados a una dirección que empieza por 0x7a3 y termina en 91c. Al compararla con la de tu billetera, descubres que estabas mirando la red Arbitrum en la app. Cambias de red y aparecen los 0,05 ETH."],"mistakes":["Pedir ayuda al soporte sin facilitar el TxID ni la red usada.","Buscar el hash en el explorador de una red distinta a la que se usó.","Creer que tener un TxID significa que los fondos ya están acreditados, sin revisar las confirmaciones."],"faq":[{"q":"¿Dónde encuentro el TxID de un retiro?","a":"En el historial de retiros del exchange o en la actividad de tu billetera. A veces aparece solo cuando la transacción ya se ha emitido a la red."},{"q":"¿Alguien puede robarme con mi TxID?","a":"No. El hash solo identifica una transacción pública; no da acceso a ninguna clave."}],"title":"¿Qué es el hash de transacción (TxID)?","description":"Qué es un TxID o hash de transacción, cómo buscarlo en un explorador de bloques y por qué lo pide el soporte.","related":[["block-explorer","Explorador de bloques","Un explorador de bloques es un sitio o herramienta que te permite buscar y ver en tiempo real las transacciones, direcciones y bloques de una blockchain pública."],["block-confirmations","Confirmaciones de bloque","Las confirmaciones de bloque son el número de bloques añadidos a la blockchain desde que se incluyó una transacción, y cuantas más tiene, más difícil es que se revierta."],["blockchain-network","Red de depósito (selección de red)","La red de depósito es la blockchain por la que se envía una criptomoneda, y elegirla bien es clave porque el mismo token, como USDT, existe en varias redes que no se comunican entre sí."],["mempool","Mempool","La mempool es la sala de espera de una blockchain: el conjunto de transacciones enviadas que aún no han sido incluidas en un bloque y esperan a ser confirmadas."]],"lesson":{"id":"E10","slug":"transfer-not-arrived","ep":10,"title":"Dice enviado, pero nunca llegó. ¿Dónde debes mirar?"},"coin":null,"tool":null,"cta":false},"address-poisoning":{"slug":"address-poisoning","cat":"wallets-security","en":"Address poisoning","contentLocale":"es","term":"Envenenamiento de direcciones","aka":["address poisoning","dirección envenenada","ataque de direcciones similares"],"short":"El envenenamiento de direcciones es una estafa en la que el atacante envía transacciones mínimas desde una dirección parecida a una que usas, para que la copies por error de tu historial.","body":[["El atacante genera una dirección cuyos primeros y últimos caracteres coinciden con los de una dirección con la que operas a menudo. Luego te envía una cantidad ínfima, un token sin valor o una transferencia de 0 ",["USDT","usdt"]," para que aparezca en tu historial."],"La trampa funciona porque muchas billeteras y exploradores abrevian las direcciones, mostrando solo el inicio y el final. Si la próxima vez copias la dirección desde el historial en lugar de la fuente original, envías los fondos al atacante. Como la transacción es irreversible, no hay forma de cancelarla.","La defensa es simple: copiar siempre las direcciones desde una fuente confiable, como la página de depósito del exchange o tu libreta de direcciones verificada, usar listas blancas y comprobar varios caracteres del medio, no solo los extremos."],"example":["Cada mes envías 3.000 USDT a tu ",["dirección de depósito","wallet-address"]," en un exchange, que empieza por 0x4F2a y termina en c91E. Un día ves en tu historial una transferencia de 0 USDT desde una dirección que también empieza por 0x4F2a y termina en c91E, pero cuyo medio es distinto. Si copias esa dirección del historial y envías 3.000 USDT, los pierdes. Si copias la dirección desde la página de depósito oficial, el ataque no tiene efecto."],"mistakes":["Copiar la dirección de destino desde el historial de transacciones.","Comprobar solo los primeros y los últimos cuatro caracteres.","Interactuar con los tokens sin valor recibidos de forma inesperada."],"faq":[{"q":"¿Recibir una transacción de 0 USDT significa que me hackearon?","a":"No. El atacante no tiene acceso a tu billetera; solo intenta que copies su dirección. Basta con ignorarla y no usarla nunca como destino."},{"q":"¿Cómo evito el envenenamiento de direcciones?","a":"Usa una libreta de direcciones verificada o lista blanca, copia desde la fuente original y haz envíos de prueba antes de montos grandes."}],"title":"¿Qué es el envenenamiento de direcciones (address poisoning)?","description":"Cómo funciona el envenenamiento de direcciones, por qué aparecen transferencias de 0 USDT y cómo evitar copiar la dirección falsa.","related":[["wallet-address","Dirección de billetera","Una dirección de billetera es la cadena de caracteres que identifica dónde recibir criptomonedas en una red concreta, parecida a un número de cuenta que puedes compartir sin riesgo."],["withdrawal-whitelist","Lista blanca de retiros","La lista blanca de retiros es una función de seguridad del exchange que permite retirar cripto solo a direcciones que has guardado y verificado previamente."],["phishing","Phishing","El phishing es un fraude en el que alguien se hace pasar por un exchange, billetera o proyecto conocido para que entregues tus contraseñas, tu frase semilla o firmes una transacción maliciosa."],["transaction-hash","Hash de transacción (TxID)","Un hash de transacción (TxID) es el identificador único de una transacción en la blockchain, que permite buscarla en un explorador de bloques y comprobar su estado."]],"lesson":{"id":"E09","slug":"pre-transfer-checklist","ep":9,"title":"Antes de transferir: no adivines ninguno de estos puntos"},"coin":null,"tool":null,"cta":false},"token-approval":{"slug":"token-approval","cat":"wallets-security","en":"Token approval (allowance)","contentLocale":"es","term":"Aprobación de tokens (allowance)","aka":["token approval","allowance","permiso de gasto","aprobación ilimitada"],"short":"Una aprobación de tokens es un permiso que firmas en tu billetera para que un contrato inteligente pueda mover una cantidad determinada de un token tuyo sin pedirte firma cada vez.","body":[["En ",["Ethereum","ethereum"]," y redes compatibles, los tokens ERC-20 no se pueden usar en una ",["DEX","dex"]," o protocolo ",["DeFi","defi"]," sin aprobar antes al contrato. Esa aprobación queda registrada en la ",["blockchain","blockchain"]," con un límite, el allowance, y sigue vigente hasta que la revocas o se consume."],["Muchas aplicaciones piden por defecto una aprobación ilimitada para ahorrarte comisiones en el futuro. Es cómodo, pero si ese contrato es malicioso o sufre un hackeo, puede vaciar todo tu saldo de ese token. Los sitios de ",["phishing","phishing"]," aprovechan justamente este mecanismo."],["Buenas prácticas: aprobar solo la cantidad que vas a usar cuando la ",["billetera","crypto-wallet"]," lo permita, desconfiar de aprobaciones en sitios que llegaron por mensaje y revisar periódicamente tus permisos con herramientas de revocación conocidas. Revocar un permiso cuesta una pequeña comisión de gas."]],"example":"Tienes 2.000 USDC y quieres cambiar 200 en una DEX. La web propone una aprobación ilimitada. En su lugar, editas el límite y apruebas 200 USDC. Haces el cambio y el allowance queda en 0. Si meses después esa DEX sufriera un fallo en el contrato, tus 1.800 USDC restantes no estarían expuestos. Con la aprobación ilimitada, el contrato podría haber movido los 1.800 USDC sin otra firma tuya.","mistakes":["Aceptar aprobaciones ilimitadas en sitios nuevos o desconocidos.","Pensar que desconectar la billetera de una web revoca las aprobaciones ya firmadas.","Firmar una aprobación cuando lo que esperabas era una simple compra o un airdrop gratuito."],"faq":[{"q":"¿Desconectar la billetera de una dApp revoca los permisos?","a":"No. Desconectar solo corta la conexión del sitio con tu billetera; la aprobación sigue registrada en la blockchain hasta que la revoques con una transacción."},{"q":"¿Cuánto cuesta revocar una aprobación de tokens?","a":"Una comisión de gas normal de la red en la que está el token. En redes de capa 2 suele ser muy baja."}],"title":"¿Qué es una aprobación de tokens (allowance)?","description":"Qué es una aprobación de tokens, por qué las aprobaciones ilimitadas son peligrosas y cómo revocar permisos en tu billetera.","related":[["smart-contract","Contrato inteligente (smart contract)","Un contrato inteligente (smart contract) es un programa publicado en una blockchain que se ejecuta automáticamente según reglas predefinidas cuando alguien interactúa con él, sin que un intermediario tenga que aprobarlo."],["phishing","Phishing","El phishing es un fraude en el que alguien se hace pasar por un exchange, billetera o proyecto conocido para que entregues tus contraseñas, tu frase semilla o firmes una transacción maliciosa."],["non-custodial-wallet","Billetera no custodial (autocustodia)","Una billetera no custodial es una billetera cripto en la que solo tú controlas las claves privadas, de modo que nadie más puede mover, congelar ni recuperar tus fondos por ti."],["dex","Exchange descentralizado (DEX)","Un exchange descentralizado (DEX) es una plataforma de intercambio de cripto que funciona con contratos inteligentes, donde operas directamente desde tu billetera sin entregar la custodia de tus fondos."]],"lesson":{"id":"E11","slug":"scam-red-flags","ep":11,"title":"Alguien dice que te hará ganar dinero. Primero mira qué te pide."},"coin":null,"tool":null,"cta":false},"dex":{"slug":"dex","cat":"defi","en":"Decentralized exchange (DEX)","contentLocale":"es","term":"Exchange descentralizado (DEX)","aka":["DEX","exchange descentralizado","decentralized exchange"],"short":"Un exchange descentralizado (DEX) es una plataforma de intercambio de cripto que funciona con contratos inteligentes, donde operas directamente desde tu billetera sin entregar la custodia de tus fondos.","body":[["La mayoría de DEX usan un ",["creador de mercado automatizado (AMM)","amm"],": en lugar de un ",["libro de órdenes","order-book"]," con compradores y vendedores, el precio se calcula a partir de los tokens depositados en pools de ",["liquidez","liquidity"],". Uniswap, PancakeSwap y Raydium son ejemplos conocidos. También existen DEX con libro de órdenes en cadena, como Hyperliquid para ",["perpetuos","perpetual-futures"],"."],["Ventajas: no necesitas cuenta ni ",["verificación de identidad","kyc"]," en la propia DEX, puedes operar tokens nuevos en cuanto alguien crea un pool y los fondos no pasan por un intermediario. Por eso, sin embargo, también se listan tokens fraudulentos con facilidad."],["Costes a tener en cuenta: la comisión del pool, el gas de la red y el ",["deslizamiento (slippage)","slippage"],", que aumenta si el pool tiene poca liquidez o tu orden es grande. Además, las transacciones pendientes pueden sufrir ataques de MEV."]],"example":"Quieres cambiar 1.000 USDC por ETH en una DEX con comisión del 0,3 %. La comisión es de 3 USDC. Si el precio indicado es de 2.500 USDC por ETH, esperarías 0,3988 ETH por los 997 USDC restantes. Fijas una tolerancia de deslizamiento del 0,5 %, así que la transacción solo se ejecutará si recibes al menos unos 0,3968 ETH. A eso súmale el gas de la red, que pagas en ETH aparte.","mistakes":["Comprar un token por su nombre sin verificar la dirección del contrato.","Poner una tolerancia de deslizamiento muy alta, lo que facilita ataques sándwich.","Olvidar que las comisiones de gas pueden superar la comisión del swap en operaciones pequeñas."],"faq":[{"q":"¿Qué diferencia hay entre un DEX y un CEX?","a":"Un CEX es una empresa que custodia tus fondos y empareja órdenes. Un DEX es un conjunto de contratos inteligentes al que te conectas con tu propia billetera."},{"q":"¿Necesito KYC para usar un DEX?","a":"Normalmente la propia DEX no lo exige, pero las interfaces web pueden bloquear ciertas regiones y la regulación varía según el país."}],"title":"¿Qué es un DEX? Exchange descentralizado explicado","description":"Qué es un exchange descentralizado, cómo funciona con pools de liquidez y qué costes tiene frente a un exchange centralizado.","related":[["amm","Creador de mercado automatizado (AMM)","Un creador de mercado automatizado (AMM) es un contrato inteligente que fija el precio de un intercambio con una fórmula basada en las reservas de un pool de liquidez, en lugar de emparejar órdenes de compradores y vendedores."],["centralized-exchange","Exchange centralizado (CEX)","Un exchange centralizado (CEX) es una empresa que opera una plataforma donde compras, vendes y operas criptomonedas, custodia tus fondos y empareja las órdenes de los usuarios en su propio libro de órdenes."],["liquidity-pool","Pool de liquidez","Un pool de liquidez es un contrato inteligente que guarda reservas de dos o más tokens para que otros usuarios puedan intercambiarlos, a cambio de comisiones que reciben quienes aportaron esos fondos."],["slippage","Deslizamiento (slippage)","El deslizamiento (slippage) es la diferencia entre el precio que esperabas al enviar una orden y el precio medio al que realmente se ejecutó, causada por falta de liquidez o por movimientos rápidos del mercado."],["perp-dex","Perp DEX (futuros perpetuos on-chain)","Un perp DEX es un exchange descentralizado que ofrece futuros perpetuos, con apalancamiento y tasa de financiación, donde operas desde tu propia billetera en lugar de depositar en un exchange centralizado."]],"lesson":null,"coin":{"slug":"uniswap","name":"Uniswap","symbol":"UNI"},"tool":"/compare","cta":false},"flash-loan":{"slug":"flash-loan","cat":"defi","en":"Flash loan","contentLocale":"es","term":"Préstamo flash (flash loan)","aka":["flash loan","préstamo relámpago","préstamo instantáneo"],"short":"Un préstamo flash (flash loan) es un préstamo sin garantía que debe pedirse y devolverse dentro de la misma transacción de blockchain; si no se devuelve, toda la transacción se revierte como si nunca hubiera ocurrido.","body":[["Funciona gracias a que una transacción en ",["Ethereum","ethereum"]," y redes similares es atómica: o se ejecuta completa o no se ejecuta. Un contrato pide prestada una gran cantidad, la usa en varios pasos y la devuelve con una pequeña comisión antes de que termine la transacción."],["Se usa para ",["arbitraje","arbitrage"]," entre ",["DEX","dex"],", para refinanciar o cerrar posiciones de préstamo sin tener capital propio y para liquidaciones. Requiere programar un contrato o usar herramientas especializadas, así que no es un producto para usuarios sin conocimientos técnicos."],"También se ha usado en ataques: un atacante pide un préstamo flash enorme, manipula el precio de un pool pequeño que un protocolo usa como oráculo y explota ese precio falso. El problema real en esos casos es el diseño del protocolo atacado, pero el préstamo flash les da escala sin capital."],"example":["Un bot detecta que ETH cotiza a 3.000 ",["USDC","usdc"]," en la DEX A y a 3.020 USDC en la DEX B. En una sola transacción pide prestados 300.000 USDC, compra 100 ETH en A, los vende en B por 302.000 USDC y devuelve los 300.000 USDC más una comisión de, por ejemplo, el 0,05 %, es decir 150 USDC. Antes de gas y ",["deslizamiento","slippage"],", gana 1.850 USDC. Si el precio cambiara y no pudiera devolver el préstamo, toda la transacción se revertiría y solo perdería el gas."],"mistakes":["Creer que un préstamo flash permite a cualquier usuario obtener dinero gratis sin riesgos ni conocimientos.","Ignorar el deslizamiento de las DEX al calcular un arbitraje con préstamo flash.","Pensar que los préstamos flash son el fallo de seguridad, cuando suelen explotar oráculos mal diseñados."],"faq":[{"q":"¿Se puede perder dinero con un flash loan?","a":"Si la operación falla, la transacción se revierte y solo pierdes el gas pagado. El riesgo mayor está en los errores del contrato que programes."},{"q":"¿Por qué los flash loans no necesitan garantía?","a":"Porque el préstamo y su devolución ocurren en la misma transacción; si no se devuelve, nada de lo ocurrido queda registrado."}],"title":"¿Qué es un préstamo flash (flash loan) en DeFi?","description":"Qué es un flash loan, cómo se pide y devuelve en una sola transacción y por qué aparece en arbitrajes y ataques DeFi.","related":[["defi-lending","Préstamos DeFi","Los préstamos DeFi son protocolos en los que depositas cripto para ganar intereses o la usas como garantía para pedir prestados otros tokens, con reglas aplicadas automáticamente por contratos inteligentes."],["oracle","Oráculo blockchain","Un oráculo blockchain es un servicio que lleva datos externos, como el precio de un activo, a los contratos inteligentes, que por sí solos no pueden consultar información fuera de la cadena."],["mev","MEV (valor máximo extraíble)","El MEV, o valor máximo extraíble, es la ganancia que pueden obtener quienes deciden el orden de las transacciones en un bloque, al incluir, excluir o reordenar operaciones de otros usuarios."],["smart-contract","Contrato inteligente (smart contract)","Un contrato inteligente (smart contract) es un programa publicado en una blockchain que se ejecuta automáticamente según reglas predefinidas cuando alguien interactúa con él, sin que un intermediario tenga que aprobarlo."]],"lesson":null,"coin":{"slug":"aave","name":"Aave","symbol":"AAVE"},"tool":null,"cta":false},"wrapped-token":{"slug":"wrapped-token","cat":"defi","en":"Wrapped token","contentLocale":"es","term":"Token envuelto (wrapped token)","aka":["wrapped token","token wrapped","WBTC","WETH"],"short":"Un token envuelto es un token que representa otro activo en una blockchain distinta o en otro estándar, respaldado uno a uno por el activo original que queda bloqueado o custodiado.","body":[["El caso más conocido es WBTC: ",["bitcoin","bitcoin"]," custodiado que se representa como token ERC-20 en ",["Ethereum","ethereum"]," para poder usarlo en ",["DeFi","defi"],". Otro es WETH, que convierte ETH nativo en un token ERC-20 compatible con contratos que solo aceptan ese estándar; en este caso el respaldo está en un contrato y no en un custodio."],"El valor de un token envuelto depende de que el respaldo exista y pueda canjearse. Si el custodio, el puente o el contrato fallan, el token puede perder su paridad con el activo original, aunque el activo original siga valiendo lo mismo.","Para el usuario, la diferencia importa al mover fondos. Un exchange puede aceptar BTC nativo en la red Bitcoin pero no WBTC en Ethereum, o al revés. Revisa siempre qué versión exacta y qué red admite el destino antes de enviar."],"example":["Tienes 0,5 BTC y quieres usarlos como garantía en un protocolo de Ethereum. Los conviertes en 0,5 WBTC a través de un servicio de wrapping, pagando por ejemplo una comisión de 0,001 BTC, así que recibes 0,499 WBTC. Con BTC a 60.000 ",["USDC","usdc"],", tu garantía vale 29.940 USDC. Si un día quieres volver a BTC nativo, debes deshacer el proceso, y otra comisión reducirá un poco esa cantidad."],"mistakes":["Enviar un token envuelto a una dirección que solo acepta el activo nativo.","Suponer que todos los tokens envueltos tienen el mismo modelo de custodia y el mismo riesgo.","Confundir varias versiones envueltas del mismo activo emitidas por puentes distintos."],"faq":[{"q":"¿WBTC es lo mismo que bitcoin?","a":"Representa bitcoin uno a uno, pero es un token en Ethereum que depende de un custodio. No es BTC nativo en la red Bitcoin."},{"q":"¿Para qué sirve WETH?","a":"Para usar ETH en contratos que esperan un token ERC-20. Se puede convertir de vuelta a ETH en cualquier momento a través de su contrato."}],"title":"¿Qué es un token envuelto (wrapped token)?","description":"Qué es un token envuelto como WBTC o WETH, cómo se respalda y qué riesgos tiene frente al activo nativo.","related":[["cross-chain-bridge","Puente entre cadenas (cross-chain bridge)","Un puente entre cadenas es un protocolo que permite mover el valor de un token de una blockchain a otra, normalmente bloqueándolo en el origen y emitiendo una representación equivalente en el destino."],["liquid-staking","Staking líquido","El staking líquido es una forma de hacer staking en la que recibes un token que representa tus fondos bloqueados más sus recompensas, y que puedes seguir usando o vender mientras tanto."],["coin-vs-token","Moneda vs token (coin vs token)","Una moneda (coin) es el activo nativo de su propia blockchain, como BTC o ETH, mientras que un token se emite sobre una blockchain ya existente mediante un contrato inteligente, como USDT en Ethereum o Tron."],["depeg","Depeg (pérdida de paridad)","Un depeg es cuando una stablecoin u otro activo vinculado pierde su paridad y cotiza claramente por encima o por debajo del valor que debería mantener, por ejemplo 1 dólar."]],"lesson":null,"coin":{"slug":"bitcoin","name":"Bitcoin","symbol":"BTC"},"tool":null,"cta":false},"kyc":{"slug":"kyc","cat":"regulation","en":"KYC (know your customer)","contentLocale":"es","term":"KYC (conoce a tu cliente)","aka":["KYC","verificación de identidad","know your customer"],"short":"El KYC es el proceso de verificación de identidad que exigen los exchanges y otros servicios regulados para confirmar quién eres antes de dejarte operar o retirar fondos.","body":["Las siglas vienen del inglés know your customer, conoce a tu cliente. En la práctica significa subir un documento de identidad, hacerte una selfie o prueba de vida y, a veces, aportar comprobante de domicilio o información sobre el origen de tus fondos.",["El KYC forma parte de las normas contra el lavado de dinero (",["AML","aml"],"). Los exchanges centralizados que operan de forma regulada lo exigen para depósitos en moneda fiat, retiros y productos como futuros. Los niveles y límites cambian según el exchange y el país."],"Hay un coste en privacidad: entregas datos personales a una empresa. Por eso conviene verificar solo en la web o app oficial del exchange, nunca enviar documentos por chat o redes sociales y revisar qué datos pide cada nivel."],"example":["Supón que un exchange tiene dos niveles. Sin KYC completo puedes depositar cripto pero no retirar más del equivalente a 1.000 USD al día. Con el nivel básico, tras subir tu documento y una selfie, el límite sube a 50.000 USD diarios y puedes comprar con tarjeta. Si quieres retirar 3.000 ",["USDT","usdt"],", necesitas completar ese nivel. Si el sistema te pide además un justificante de fondos, puedes aportar un extracto bancario que muestre de dónde vienen."],"mistakes":["Enviar fotos de tu documento a supuestos agentes de soporte por Telegram o WhatsApp.","Usar los datos o la cuenta de otra persona para pasar el KYC.","Depositar grandes sumas antes de comprobar si podrás retirarlas con tu nivel de verificación."],"faq":[{"q":"¿Es obligatorio hacer KYC en un exchange?","a":"En los exchanges regulados, casi siempre para operar con moneda fiat y para retirar por encima de ciertos límites. Las reglas exactas dependen del exchange y del país."},{"q":"¿Qué pasa con mis datos de KYC?","a":"El exchange los guarda para cumplir la normativa y puede compartirlos con autoridades si la ley lo exige. Revisa su política de privacidad antes de verificarte."}],"title":"¿Qué es el KYC en cripto? Verificación de identidad","description":"Qué es el KYC en un exchange de cripto, qué datos te pedirán, por qué se exige y cómo proteger tu información personal.","related":[["aml","AML (prevención del lavado de dinero)","AML es el conjunto de leyes, controles y procesos que usan los exchanges y otras entidades financieras para detectar y prevenir el lavado de dinero y la financiación del terrorismo."],["travel-rule","Regla de viaje (Travel Rule)","La regla de viaje es una norma internacional contra el lavado de dinero que obliga a los proveedores de criptoactivos a enviar y recibir los datos del remitente y del beneficiario en las transferencias."],["no-kyc-exchange","Exchange sin KYC","Un exchange sin KYC es una plataforma de intercambio de criptomonedas que permite operar, y a veces retirar, sin verificar tu identidad con documentos, o solo con límites bajos."],["centralized-exchange","Exchange centralizado (CEX)","Un exchange centralizado (CEX) es una empresa que opera una plataforma donde compras, vendes y operas criptomonedas, custodia tus fondos y empareja las órdenes de los usuarios en su propio libro de órdenes."],["vasp","VASP (proveedor de servicios de activos virtuales)","Un VASP es una empresa que presta servicios con criptoactivos para terceros, como cambio, custodia o transferencias, y por eso está sujeta a normas de registro, KYC y prevención del lavado."]],"lesson":{"id":"E05","slug":"kyc-who-gets-your-id","ep":5,"title":"¿Cómo funciona el KYC y a quién debes darle tu documento?"},"coin":null,"tool":null,"cta":false},"demo-trading":{"slug":"demo-trading","cat":"exchange-features","en":"Demo trading","contentLocale":"es","term":"Trading demo (cuenta de práctica)","aka":["cuenta demo","trading simulado","paper trading","demo trading"],"short":"El trading demo es una modalidad de práctica que ofrecen los exchanges en la que operas con fondos ficticios a precios reales, para aprender sin arriesgar tu dinero.","body":[["Activas el modo demo y recibes un saldo virtual, por ejemplo en ",["USDT","usdt"],". Puedes abrir órdenes en spot o futuros, probar el ",["apalancamiento","leverage"],", el ",["stop loss","stop-loss"]," y el ",["take profit","take-profit"],", y ver cómo funcionan la ",["tasa de financiación","funding-rate"]," y la ",["liquidación","liquidation"],"."],"Es especialmente útil para entender los futuros perpetuos antes de usarlos con dinero real: cómo se calcula el precio de liquidación, qué pasa con el margen aislado o cruzado y cómo afectan las comisiones. Varios exchanges grandes lo ofrecen, con nombres y reglas propios.","Su límite es psicológico. Perder dinero ficticio no duele, así que puedes tomar riesgos que no tomarías en real. Además, las ejecuciones en demo pueden ser más fáciles que en el mercado real, sobre todo en órdenes grandes."],"example":"Supón que en demo tienes 10.000 USDT ficticios y abres un largo de BTC a 50.000 con 20x usando 500 USDT de margen aislado, una posición de 10.000 USDT. Una caída de alrededor del 5 % te acerca a la liquidación, y antes de ella ya habrías perdido casi todo el margen. Si en la práctica ves que te liquidan dos veces en una semana con ese apalancamiento, es una señal clara de bajar a 3x o 5x antes de usar dinero real.","mistakes":["Usar en demo un apalancamiento que nunca usarías en real.","Pasar a real tras pocos días de buenos resultados en demo.","Ignorar las comisiones y la financiación porque el saldo es ficticio."],"faq":[{"q":"¿El trading demo usa precios reales?","a":"Suele usar precios reales o muy cercanos, pero la ejecución puede ser distinta a la del mercado real, sobre todo en órdenes grandes."},{"q":"¿Se puede retirar lo ganado en demo?","a":"No. Los fondos son ficticios y no se pueden retirar ni pasar a la cuenta real."}],"title":"¿Qué es el trading demo? Practicar sin riesgo","description":"Qué es el trading demo en un exchange, cómo practicar futuros con fondos ficticios y cuáles son sus limitaciones.","related":[["perpetual-futures","Futuros perpetuos (perps)","Los futuros perpetuos son contratos de futuros sin fecha de vencimiento que siguen el precio spot gracias a pagos periódicos entre largos y cortos llamados tasa de financiación."],["leverage","Apalancamiento","El apalancamiento es usar capital prestado para abrir una posición mayor que tu margen, de modo que las ganancias y las pérdidas se multiplican en la misma proporción."],["copy-trading","Copy trading","El copy trading es una función de los exchanges que permite copiar automáticamente las operaciones de otro trader, llamado líder, en tu propia cuenta y en la proporción que elijas."],["position-sizing","Tamaño de posición","El tamaño de posición es la cantidad de capital que asignas a una operación, calculada para que, si toca tu stop loss, pierdas solo un porcentaje fijo de tu cuenta."]],"lesson":{"id":"E19","slug":"what-leverage-does","ep":19,"title":"Apalancamiento 10x: ¿más dinero o más riesgo?"},"coin":null,"tool":null,"cta":true}});
